package br.com.fastfps.util; public final class FastMath{private static final float[]S=new float[65536];private static final float K=65536f/((float)Math.PI*2f);static{for(int i=0;i<S.length;i++)S[i]=(float)Math.sin(i*Math.PI*2d/S.length);}public static float sin(float r){return S[(int)(r*K)&65535];}public static float cos(float r){return S[(int)(r*K+16384)&65535];}public static int floor(double v){int i=(int)v;return v<i?i-1:i;}public static int fastAbs(int v){return(v^(v>>31))-(v>>31);}private FastMath(){}}
